The DHT22 temperature and humidity sensor! A popular and widely used low-cost IoT sensor.

Calibrating a DHT22 sensor is a crucial step to ensure accurate readings. The calibration process involves adjusting the sensor's offset values to account for any manufacturing tolerances or environmental factors that may affect its readings. Here's a code example in Arduino to demonstrate the calibration process:
```cpp
// Include the DHT library
#include <DHT.h>

// Define the pin connections
#define DHTPIN 2
#define DHTTYPE DHT22

// Create a DHT sensor object
DHT dht(DHTPIN, DHTTYPE);

// Define the calibration variables
int OFFSET_TEMP = 0;  // Default offset value for temperature (0 means no offset)
int OFFSET_HUM = 0;   // Default offset value for humidity (0 means no offset)

void setup() {
  Serial.begin(9600);
  dht.begin();
}

void loop() {
  // Read the temperature and humidity values from the sensor
  float temp = dht.readTemperature();
  float hum = dht.readHumidity();

  // Apply the calibration offsets
  temp += OFFSET_TEMP;
  hum += OFFSET_HUM;

  // Print the calibrated values to the serial monitor
  Serial.print("Temperature: ");
  Serial.print(temp);
  Serial.print("°C");
  Serial.print("  Humidity: ");
  Serial.print(hum);
  Serial.println("%");

  // Wait for 2 seconds before taking the next reading
  delay(2000);
}

void calibrate() {
  // Calibrate the temperature offset
  Serial.println("Calibrating temperature offset...");
  int tempOffset = 0;  // Initialize the temperature offset value

  for (int i = 0; i < 10; i++) {
    dht.begin();
    float temp = dht.readTemperature();
    Serial.print("Temperature reading: ");
    Serial.print(temp);
    Serial.println("°C");

    // Ask the user to input a reference temperature value
    float refTemp = analogRead(A0);  // Replace with your own reference temperature sensor
    Serial.print("Reference temperature: ");
    Serial.print(refTemp);
    Serial.println("°C");

    // Calculate the temperature offset
    tempOffset = (refTemp - temp) / 10;
    Serial.print("Temperature offset: ");
    Serial.print(tempOffset);
    Serial.println("°C");

    // Store the temperature offset value
    OFFSET_TEMP = tempOffset;

    // Wait for 2 seconds before taking the next reading
    delay(2000);
  }

  // Calibrate the humidity offset
  Serial.println("Calibrating humidity offset...");
  int humOffset = 0;  // Initialize the humidity offset value

  for (int i = 0; i < 10; i++) {
    dht.begin();
    float hum = dht.readHumidity();
    Serial.print("Humidity reading: ");
    Serial.print(hum);
    Serial.println("%");

    // Ask the user to input a reference humidity value
    float refHum = analogRead(A1);  // Replace with your own reference humidity sensor
    Serial.print("Reference humidity: ");
    Serial.print(refHum);
    Serial.println("%");

    // Calculate the humidity offset
    humOffset = (refHum - hum) / 10;
    Serial.print("Humidity offset: ");
    Serial.print(humOffset);
    Serial.println("%");

    // Store the humidity offset value
    OFFSET_HUM = humOffset;

    // Wait for 2 seconds before taking the next reading
    delay(2000);
  }

  Serial.println("Calibration complete!");
}
```
