```
interface IGTMConfig {
  // GTM container ID
  containerId: string;
}

class GTMLibrary {
  private _config: IGTMConfig;

  constructor(config: IGTMConfig) {
    this._config = config;
  }

  public addGTM.Snippet(): void {
    const script = document.createElement('script');
    script.src = `https://www.googletagmanager.com/gtag/js?id=${this._config.containerId}`;
    script.defer = true;
