    class Program
    {
        static void Main(string[] args)
        {
            string folderPath = @"C:\Path\To\Folder"; // replace with your folder path
            string pattern = "*.zip"; // pattern for zip files

            foreach (string zipFile in Directory.EnumerateFiles(folderPath, pattern))
            {
                using (ZipFile zip = ZipFile.Read(zipFile))
                {
                    foreach (ZipEntry entry in zip.Entries.Where(e => e.FileName.EndsWith(".txt")))
                    {
                        string text = entry.OpenReader().ReadToEnd();
                        int count = Regex.Matches(text, @"\bINFO\b", RegexOptions.IgnoreCase).Count;
                        Console.WriteLine($"File: {entry.FileName}, INFO count: {count}");
                    }
                }
            }
        }
    }
}
```
