Here is a generic Java code to convert SQL query to MongoDB query. This code is just a basic example and might need to be adapted to your specific use case.

Assumptions:

* MongoDB's BSON type system is used to convert SQL types to MongoDB types.
* SQL "Like" operator is converted to MongoDB's "regex" operator.
* SQL "In" operator is converted to MongoDB's "$in" operator.
* SQL "Between" operator is converted to MongoDB's "$gte" and "$lte" operators.
* SQL "Having" clause is converted to MongoDB's "aggregate" method.
* SQL "OrderBy" and "Limit" clauses are converted to MongoDB's "sort" and "limit" methods.

```java
import com.mongodb.client.MongoClients;
import com.mongodb.client.MongoClient;
import com.mongodb.client.MongoCollection;
import org.bson.Document;

import java.util.ArrayList;
import java.util.List;

public class SQLToMongoQueryConverter {
    private final MongoClient mongoClient;
    private final String databaseName;
    private final String collectionName;

    public SQLToMongoQueryConverter(String mongoUri, String databaseName, String collectionName) {
        this.mongoClient = MongoClients.create(mongoUri);
        this.databaseName = databaseName;
        this.collectionName = collectionName;
    }

    public Document convertSQLQueryToMongoQuery(String sqlQuery) {
        sqlQuery = sqlQuery.trim().toUpperCase();

        // Convert "SELECT" statement to "find" method
        if (sqlQuery.startsWith("SELECT ")) {
            sqlQuery = sqlQuery.replace("SELECT ", "find({");
        }

        // Convert "USING" statement to "cursor" method
        if (sqlQuery.contains("USING")) {
            sqlQuery = sqlQuery.replace("USING", "cursor");
        }

        // Convert "WHERE" clause to "filter" method
        if (sqlQuery.contains("WHERE")) {
            int whereIndex = sqlQuery.indexOf("WHERE");
            sqlQuery = sqlQuery.replace("WHERE", " filter == {");
            sqlQuery = sqlQuery.substring(0, whereIndex) + sqlQuery.substring(whereIndex + 6).trim() + "}";
        }

        // Convert "And" and "Or" operators to MongoDB's "$and" and "$or" operators
        sqlQuery = sqlQuery.replace(" AND ", " && ");
        sqlQuery = sqlQuery.replace(" OR ", " || ");

        // Convert "Like" operator to MongoDB's "regex" operator
        sqlQuery = sqlQuery.replace(" LIKE ", " regex /");

        // Convert "In" operator to MongoDB's "$in" operator
        sqlQuery = sqlQuery.replace(" IN (", " { $in: [");
        sqlQuery = sqlQuery.replace(") ", " ] }");

        // Convert "Between" operator to MongoDB's "$gte" and "$lte" operators
        sqlQuery = sqlQuery.replace(" BETWEEN ", " { $gte: ");
        sqlQuery = sqlQuery.replace(" AND ", ", $lte: ");

        // Convert "Having" clause to MongoDB's "aggregate" method
        if (sqlQuery.contains("HAVING")) {
            int havingIndex = sqlQuery.indexOf("HAVING");
            sqlQuery = sqlQuery.replace("HAVING", " aggregate ");
            sqlQuery = sqlQuery.substring(0, havingIndex) + sqlQuery.substring(havingIndex + 7).trim() + "}";
        }

        // Convert "OrderBy" and "Limit" clauses to MongoDB's "sort" and "limit" methods
        if (sqlQuery.contains("ORDER BY")) {
            int orderByIndex = sqlQuery.indexOf("ORDER BY");
            sqlQuery = sqlQuery.substring(0, orderByIndex) + ".sort(";
            sqlQuery = sqlQuery.substring(orderByIndex).trim();
        }

        if (sqlQuery.contains("LIMIT")) {
            int limitIndex = sqlQuery.indexOf("LIMIT");
            sqlQuery = sqlQuery.substring(0, limitIndex) + ".limit(";
            sqlQuery = sqlQuery.substring(limitIndex).trim();
        }

        // Convert "Delete" statement to "deleteOne" method
        if (sqlQuery.startsWith("DELETE FROM ")) {
            sqlQuery = sqlQuery.replace("DELETE FROM ", " deleteOne({");
        }

        // Convert "Insert" statement to "insertOne" method
        if (sqlQuery.startsWith("INSERT INTO ")) {
            sqlQuery = sqlQuery.replace("INSERT INTO ", " insertOne({");
        }

        // Convert "Update" statement to "updateOne" method
        if (sqlQuery.startsWith("UPDATE ")) {
            sqlQuery = sqlQuery.replace("UPDATE ", " updateOne({");
        }

        Document mongoQuery = Document.parse(sqlQuery);

        MongoCollection<Document> collection = mongoClient.getDatabase(databaseName).getCollection(collectionName);
        return mongoQuery;
    }
}
```

