        cout << "Patching 0x002D32CC: 75 -> EB\n";
    }

    file.seekg(0x002D32CD);
    file.read(bytes, 2);
    cout << "Read  " << int(bytes[0]) + (int(bytes[1]) << 8) << " at 0x002D32CD\n";
    if (int(bytes[0]) + (int(bytes[1]) << 8) == 0x0047) {
        bytes[0] = MAGIC_NUMBER;
