import com.google.cloud.vision.v1.EntityAnnotation;
import com.google.cloud.vision.v1.Feature;
import com.google.cloud.vision.v1.Image;
import com.google.cloud.vision.v1.ImageAnnotatorClient;
import org.opencv.core.Core;
import org.opencv.core.Mat;
import org.opencv.imgcodecs.Imgcodecs;

public class ImagePersonDetection {
    public static void main(String[] args) throws IOException {
        // Set the URL of the image
        String url = "https://example.com/image.jpg";

        // Load the image from the URL
        Mat mat = Imgcodecs.imread(url);

        // Convert the image to a byte array
        byte[] imageBytes = new byte[mat.toArray()[0].length];
        System.arraycopy(mat.toArray()[0], 0, imageBytes, 0, imageBytes.length);

        // Create a Google Cloud Vision API client
        ImageAnnotatorClient client = ImageAnnotatorClient.create();

        // Create a list to store the image annotation results
        List<AnnotateImageRequest> requests = Arrays.asList(
                AnnotateImageRequest.newBuilder()
                        .addAllFeatures(Arrays.asList(
                                Feature.newBuilder().setType(Feature.Type.LABEL_DETECTION).build(),
                                Feature.newBuilder().setType(Feature.Type.IMAGE_PROPERTIES).build()
                        ))
                        .setImage(Image.newBuilder().setLayout(Image.MaN).
                                .setContent(ByteString.copyFrom(imageBytes)).build()) )

        // Perform image annotation
        BatchAnnotateImagesResponse response = client.batchAnnotateImages(requests);

        // Get the image annotation results
        AnnotateImageResponse annotationResponse = response.getResponses().get(0);

        // Check if the image contains a person
        boolean containsPerson = false;
        for (EntityAnnotation entity : annotationResponse.getLabelAnnotations()) {
            if (entity.getDescription().equals("person")) {
                containsPerson = true;
                break;
            }
        }

        // Print the result
        System.out.println("Image contains a person: " + containsPerson);

        // Clean up
        client.close();
    }
}
```
