Here is a C++ program that renames every file inside a given folder with a 3-digit number, sorted by file creation date:
```cpp
#include <iostream>
#include <filesystem>
#include <vector>
#include <algorithm>
#include <ctime>

// Function to rename a file with a 3-digit number
void renameFile(std::filesystem::path filePath, int index) {
    std::time_t t = std::time(0); // Current time
    std::tm* now = std::localtime(&t);
    std::ostringstream oss;
    oss << "File_" << std::setw(3) << std::setfill('0') << index << "_" << now->tm_yyyy << "_" << now->tm_mon << "_" << now->tm_mday << "_" << now->tm_hour << "_" << now->tm_min << "_" << now->tm_sec << ".txt";
    std::filesystem::rename(filePath, oss.str());
}

int main() {
    // Get the folder path from the user
    std::cout << "Enter the folder path: ";
    std::string folderPath;
    std::cin >> folderPath;

    // Initialize a vector to store the file paths
    std::vector<std::filesystem::path> file Paths;

    // Traverse the folder and its subfolders
    for (auto& entry : std::filesystem::recursive_directory_iterator(folderPath)) {
        if (entry.is_regular_file()) {
            filePaths.push_back(entry.path());
        }
    }

    // Sort the file paths by file creation date
    std::sort(filePaths.begin(), filePaths.end(), [](const auto& a, const auto& b) {
        return std::filesystem::last_write_time(a) < std::filesystem::last_write_time(b);
    });

    // Rename each file with a 3-digit number
    int index = 1;
    for (const auto& filePath : filePaths) {
        renameFile(filePath, index);
        index++;
    }

    return 0;
}
```
