**Step 5: Create a controller for handling CSV uploads**

Create a new controller, `CsvUploadController`, that handles CSV file uploads and parses the data:
```csharp
[ApiController]
[Route("api/[controller]")]
public class CsvUploadController : ControllerBase
{
    private readonly CosmosClient _cosmosClient;

    public CsvUploadContainer CsvUploadContainer { get; set; }

    public CsvUploadController(CosmosClient cosmosClient)
    {
        _cosmosClient = cosmosClient;
        CsvUploadContainer = _cosmosClient.GetContainer("your_database_name", "your_container_name");
    }

    [HttpPost]
    public async Task<IActionResult> UploadCsvFile(IFormFile file)
    {
        using (StreamReader reader = new StreamReader(file.OpenReadStream()))
        {
            string csvContent = await reader.ReadToEndAsync();
            CsvDataModel[] csvData = GetCsvDataFromContent(csvContent);
            await SaveCsvDataToCosmosDb(csvData);
            return Ok("CSV file uploaded successfully");
        }
    }

    private CsvDataModel[] GetCsvDataFromContent(string csvContent)
    {
        using (StringReader stringReader = new StringReader(csvContent))
        {
            using (CsvReader csvReader = new CsvReader(stringReader, CultureInfo.InvariantCulture))
            {
                return csvReader.GetRecords<CsvDataModel>().ToArray();
            }
        }
    }

    private async Task SaveCsvDataToCosmosDb(CsvDataModel[] csvData)
    {
        foreach (var csvDataItem in csvData)
        {
            await CsvUploadContainer.CreateItemAsync(csvDataItem);
        }
    }
}
```
