```
pragma solidity ^0.8.0;

import "https://github.com/OpenZeppelin/openzeppelin-solidity/contracts/token/ERC721/SafeERC721.sol";
import "https://github.com/OpenZeppelin/openzeppelin-solidity/contracts/utils/Counters.sol";

contract MyNFTCollection {
    using Counters for Counters.Counter;

    // Mapping of NFTs to their owners
    mapping (address => mapping (uint256 => NFT)) private _ownedNFTs;

    // Mapping of NFT IDs to their metadata
    mapping (uint256 => NFTMetadata) public nftMetadata;

    // Total supply of NFTs
    uint256 public totalSupply;

    // Counter for tracking NFT IDs
    Counters.Counter private _nftIdCounter;

    // Mapping of NFT owners to their balances
    mapping (address => uint256) public balances;

    // Event emitted when an NFT is minted
    event Mint(address indexed to, uint256 indexed id);

    // Event emitted when an NFT is transferred
    event Transfer(address indexed from, address indexed to, uint256 indexed id);

    // Event emitted when an NFT is burned
    event Burn(address indexed owner, uint256 indexed id);

    struct NFT {
        uint256 id;
        address owner;
    }

    struct NFTMetadata {
        string name;
        string description;
        uint256 price;
    }

    constructor() public {
        totalSupply = 0;
        _nftIdCounter = Counters.Counter(0);
    }

    function mint(address to, NFTMetadata metadata) public {
        require(to != address(0), "Cannot mint to the zero address");
        require(totalSupply < 100, "Maximum supply reached");

        uint256 nftId = _nftIdCounter.current();
        _nftIdCounter.increment();

        nftMetadata[nftId] = metadata;
        _ownedNFTs[to][nftId] = NFT(nftId, to);
        balances[to] = balances[to] + 1;

        totalSupply = totalSupply + 1;

        emit Mint(to, nftId);
    }

    function transfer(address from, address to, uint256 id) public {
        require(_ownedNFTs[from][id].id == id, "Invalid NFT ID");
        require(_ownedNFTs[from][id].owner == from, "You don't own this NFT");
        require(to != address(0), "Cannot transfer to the zero address");

        _ownedNFTs[from][id].owner = to;
        _ownedNFTs[to][id] = _ownedNFTs[from][id];

        balances[from] = balances[from] - 1;
        balances[to] = balances[to] + 1;

        emit Transfer(from, to, id);
    }

    function burn(uint256 id) public {
        require(_ownedNFTs[msg.sender][id].id == id, "Invalid NFT ID");
        require(_ownedNFTs[msg.sender][id].owner == msg.sender, "You don't own this NFT");

        delete _ownedNFTs[msg.sender][id];
        balances[msg.sender] = balances[msg.sender] - 1;

        totalSupply = totalSupply - 1;

        emit Burn(msg.sender, id);
    }
}
```
