% Define the robot arm model
% The robot arm has 2 links, each with a length of 1 unit
% The joints are revolute ( rotary) and the axes are perpendicular
% The base of the robot is at the origin (0,0)

link1_length = 1;
link2_length = 1;
joint1_axis = [0, 0, 1];  % z-axis
joint2_axis = [0, 0, 1];  % z-axis

% Define the target position
target_x = 1.5;
target_y = 0.5;

% Define the initial position
initial_x = 0;
initial_y = 0;
initial_theta1 = 0;
initial_theta2 = 0;

% Define the control gains
Kp = 10;  % proportional gain
Ki = 1;  % integral gain

% Define the simulation time
t_sim = 10;

% Initialize the simulation variables
t = 0;
x = initial_x;
y = initial_y;
theta1 = initial_theta1;
theta2 = initial_theta2;
error_x = target_x - initial_x;
error_y = target_y - initial_y;
integral_x = 0;
integral_y = 0;

% Simulation loop
while t < t_sim
    % Compute the end-effector position using the forward kinematics
    x_end = link1_length * cos(theta1) + link2_length * cos(theta1 + theta2);
    y_end = link1_length * sin(theta1) + link2_length * sin(theta1 + theta2);

    % Compute the error between the end-effector position and the target position
    error_x = target_x - x_end;
    error_y = target_y - y_end;

    % Compute the integral terms
    integral_x = integral_x + error_x * dt;
    integral_y = integral_y + error_y * dt;

    % Compute the control signals using proportional and integral control
    u1 = -Kp * error_x - Ki * integral_x;
    u2 = -Kp * error_y - Ki * integral_y;

    % Update the joint angles using the control signals
    theta1 = theta1 + u1 * dt;
    theta2 = theta2 + u2 * dt;

    % Update the end-effector position
    x = link1_length * cos(theta1) + link2_length * cos(theta1 + theta2);
    y = link1_length * sin(theta1) + link2_length * sin(theta1 + theta2);

    % Update the time
    t = t + dt;
end

% Plot the simulation results
figure;
plot(x, y);
xlabel('X Position');
ylabel('Y Position');
title('Robot Arm Trajectory');

% Plot the control signals
figure;
plot(u1, u2);
xlabel('Time');
ylabel('Control Signals');
title('Control Signals over Time');
